import pytest

from plasmid import (
    ENZYMES,
    count_sites,
    digest,
    find_sites,
    fragment_sizes,
    is_unique_cutter,
)


@pytest.fixture
def seq():
    return "GAATTC" + "A" * 20 + "AAGCTT" + "C" * 10 + "AAGCTT" + "G" * 12


def test_length(seq):
    assert len(seq) == 60


def test_site_counts(seq):
    assert count_sites(seq, ENZYMES["EcoRI"]["site"]) == 1   # GAATTC
    assert count_sites(seq, ENZYMES["HindIII"]["site"]) == 2  # AAGCTT x2
    assert count_sites(seq, ENZYMES["BamHI"]["site"]) == 0    # GGATCC absent


def test_unique_cutter_flags(seq):
    assert is_unique_cutter(seq, ENZYMES["EcoRI"]["site"]) is True
    assert is_unique_cutter(seq, ENZYMES["HindIII"]["site"]) is False
    assert is_unique_cutter(seq, ENZYMES["BamHI"]["site"]) is False


def test_hindiii_digest_fragments(seq):
    assert digest(seq, "HindIII") == [16, 44]


def test_ecori_digest_single_fragment(seq):
    assert digest(seq, "EcoRI") == [60]


def test_bamhi_digest_no_cut(seq):
    assert digest(seq, "BamHI") == [60]


def test_site_spanning_origin_found_after_rotation(seq):
    rotated = seq[3:] + seq[:3]  # move 'GAA' to the end
    # EcoRI site now spans the origin: 'GAA' + 'TTC'
    assert seq.startswith("GAATTC")
    assert not rotated.startswith("GAATTC")
    assert find_sites(rotated, ENZYMES["EcoRI"]["site"]) == [57]


def test_fragment_multiset_rotation_invariant(seq):
    for shift in range(len(seq)):
        rotated = seq[shift:] + seq[:shift]
        for name in ENZYMES:
            assert digest(rotated, name) == digest(seq, name), (name, shift)


def test_no_cuts_returns_full_length():
    assert fragment_sizes("ACGTACGT", []) == [8]


def test_single_site_full_length():
    assert fragment_sizes("ACGTACGT", [3]) == [8]


def test_overlapping_origin_sites_counted_once():
    # Site 'AAAA' appears twice on a circle of all A's of length 4? Use
    # length 6: occurrences at 0,1,2 -> exactly 3, no double counting.
    assert count_sites("AAAAAA", "AAAA") == 3

